       event.preventDefault();

       let score = 0;

       for (const [question, correctAnswers] of Object.entries(answerKey)) {
         const selectedAnswers = Array.from(form.querySelectorAll(`input[name="${question}"]:checked`))
           .map((input) => input.value)
           .sort();

         const expectedAnswers = [...correctAnswers].sort();
         const isCorrect = selectedAnswers.length === expectedAnswers.length &&
           selectedAnswers.every((value, index) => value === expectedAnswers[index]);

         if (isCorrect) {
           score += 1;
         }
       }

       result.className = score === Object.keys(answerKey).length ? "success" : "";
       result.textContent = `You scored ${score} out of ${Object.keys(answerKey).length}.`;
     });
   </script>
 </body>
 </html>

